package com.oms.order.service;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.*;

/** Replacement is scoped to HH+round; sales auto-allocation is not reused for exchange-out lines. */
@Service public class ExchangeAutomaticFulfillment {
    @Resource OrderRepository repository;
    @Resource ExchangeService exchanges;
    @Resource ExchangeFulfillment fulfillment;
    @Resource OrderAllocationService allocation;
    @Resource OrderCarrierService carriers;
    @Resource OrderShipmentDispatchService dispatch;
    @Resource ExchangeFlowPolicy policies;
    @Resource ExchangeOperationJournal journal;
    @Resource ExchangeExecution execution;
    Map<String,Object> advance(String c,Map<String,Object> e,Map<String,Object> p,long v){
        long id=number(e,"id");boolean unshipped=ExchangeFulfillment.unshipped(e),platform="PLATFORM".equals(text(e,"source_kind"));
        if(e.get("fulfillment_line_id")==null){require(ExchangeFlowPolicy.on(p,"auto_allocate"),"自动换出分仓未启用，请从换出发货入口处理");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_allocate");fulfillment.materialize(c,id);e=exchanges.row(c,id,false);}
        if(unshipped)reviewReplacementOrder(c,e,p);
        if(!"FULL".equals(text(e,"allocation_status"))&&!unshipped){require(ExchangeFlowPolicy.on(p,"auto_allocate"),"自动换出分仓未启用");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_allocate");Map<String,Object> result=allocation.allocateExchange(c,id,number(e,"control_version"),ExchangeFlowPolicy.ACTOR);e=exchanges.row(c,id,false);if(!"FULL".equals(text(e,"allocation_status")))return outcome(c,id,v,"WAITING","ALLOCATION","WAIT_ALLOCATION",text(result,"message").isEmpty()?"换出仓库库存未满足完整分仓，保留申请数量":text(result,"message"));}
        if(unshipped){Map<String,Object> order=repository.db().queryForMap("SELECT * FROM oms_order WHERE company_code=? AND id=?",c,e.get("order_id"));if(!"FULL".equals(text(order,"allocation_status"))){require(ExchangeFlowPolicy.on(p,"auto_allocate"),"未发货换品后自动分仓未启用");List<Map<String,Object>> results=allocation.allocate(c,map("items",Collections.singletonList(map("id",e.get("order_id"),"control_version",order.get("control_version")))),ExchangeFlowPolicy.ACTOR);if(results.isEmpty()||Boolean.FALSE.equals(results.get(0).get("success")))return outcome(c,id,v,"WAITING","ALLOCATION","WAIT_ALLOCATION","原SO换品后等待正式分仓结果");}}
        List<Map<String,Object>> ships=repository.db().query("SELECT * FROM oms_order_shipment WHERE company_code=? AND "+(unshipped?"order_id=? AND business_type='SALE'":"exchange_id=? AND business_type='EXCHANGE' AND fulfillment_round="+ExchangeRounds.numberOf(e))+" AND status NOT IN ('VOIDED','CLOSED') ORDER BY id LIMIT 101",ROW,c,unshipped?e.get("order_id"):id);require(ships.size()<=100,"换出发货单过多，请核对完整范围");
        for(Map<String,Object> ship:ships){
            if("SHIPPED".equals(text(ship,"status")))continue;
            if(!"MATCHED".equals(text(ship,"carrier_match_status"))){require(ExchangeFlowPolicy.on(p,"auto_carrier"),"自动匹配快递未启用，请在原发货单确认快递");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_carrier");List<Map<String,Object>> result=carriers.match(c,map("mode","AUTO","items",Collections.singletonList(map("id",ship.get("id"),"control_version",ship.get("control_version")))),ExchangeFlowPolicy.ACTOR);require(result.size()==1&&!Boolean.FALSE.equals(result.get(0).get("success")),result.isEmpty()?"快递匹配未完成":text(result.get(0),"message"));return outcome(c,id,v,"WAITING","CARRIER","CARRIER_MATCHED","已按店铺快递规则匹配换出发货单");}
            List<Map<String,Object>> intents=repository.db().query("SELECT state,last_error FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=?",ROW,c,ship.get("id"));
            if(intents.isEmpty()&&"WAIT_DISPATCH".equals(text(ship,"status"))){require(ExchangeFlowPolicy.on(p,"auto_dispatch"),"自动下发换出仓库未启用，请在原发货单确认下发");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_dispatch");List<Map<String,Object>> result=dispatch.submit(c,map("items",Collections.singletonList(map("id",ship.get("id"),"control_version",ship.get("control_version")))),ExchangeFlowPolicy.ACTOR);require(result.size()==1&&Boolean.TRUE.equals(result.get(0).get("success")),result.isEmpty()?"下发尚未提交":text(result.get(0),"message"));return outcome(c,id,v,"WAITING","DISPATCH","DISPATCH_SUBMITTED","已登记原发货单下发，等待仓库确认");}
            if(!intents.isEmpty()&&Arrays.asList("PENDING","PROCESSING","UNKNOWN").contains(text(intents.get(0),"state"))){dispatch.process(c,number(ship,"id"));return outcome(c,id,v,"WAITING","DISPATCH","DISPATCH_PENDING","继续核对原仓库请求；不重新创建未知结果的发货单");}
            if(!intents.isEmpty()&&"FAILED".equals(text(intents.get(0),"state")))throw new IllegalArgumentException("原发货单下发已明确失败："+text(intents.get(0),"last_error")+"；请核对原单，不定时重复下发");
        }
        long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?",Long.class,c,e.get("fulfillment_line_id"));
        if(shipped!=ExchangeRounds.quantityOf(e))return outcome(c,id,v,"WAITING","SHIPMENT","WAIT_ACTUAL_OUTBOUND","等待本轮换出实际出库；仓库接单不代表已经发货");
        require(repository.db().queryForObject("SELECT COALESCE(SUM(p.quantity),0) FROM oms_order_shipment_package_line p JOIN oms_order_shipment_line l ON l.company_code=p.company_code AND l.id=p.shipment_line_id WHERE l.company_code=? AND l.order_line_id=?",Long.class,c,e.get("fulfillment_line_id"))==shipped,"实际出库包裹数量尚未完整关联，请核对原回执");
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_outbound o JOIN oms_order_shipment_line l ON l.company_code=o.company_code AND l.shipment_id=o.shipment_id WHERE l.company_code=? AND l.order_line_id=? AND o.state<>'COMPLETED'",Long.class,c,e.get("fulfillment_line_id"))==0,"原换出回执尚未完整入账，请核对原消息");
        if(!platform){repository.db().update("UPDATE oms_exchange SET state='COMPLETED',stage='FINISHED',next_attempt=NULL WHERE company_code=? AND id=?",c,id);return outcome(c,id,v,"DONE","FINISHED","INTERNAL_COMPLETED","协商换货已完成实际退回及换出；未冒充平台换货成功");}
        if("5".equals(text(e,"platform_status"))){repository.db().update("UPDATE oms_exchange SET state='COMPLETED',stage='FINISHED',next_attempt=NULL WHERE company_code=? AND id=?",c,id);return outcome(c,id,v,"DONE","FINISHED","PLATFORM_COMPLETED","本地实收实发及平台换货成功均已确认");}
        if("13".equals(text(e,"platform_status"))){Map<String,Object> response=exchanges.call(c,number(e,"channel_id"),"DETAIL",map("dispute_id",e.get("dispute_id"),"fields",ExchangeService.FIELDS));new PlatformExchangeService(repository,exchanges).ingest(c,number(e,"channel_id"),object(response.get("exchange")),"自动换货完成核对");return outcome(c,id,v,"WAITING","PLATFORM_CONFIRMATION","WAIT_BUYER_CONFIRM","换出已实际发货并回传，等待平台确认换货成功");}
        require("12".equals(text(e,"platform_status")),"平台当前阶段不允许回传换出物流，请核对");require(ExchangeFlowPolicy.on(p,"auto_consign"),"自动回传换出物流未启用");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_consign");
        Map<String,Object> input=map("control_version",e.get("control_version"),"operation","CONSIGN","reason","商家自动换货规则：本轮实际出库及包裹数量完整，回传真实物流");Map<String,Object> op=journal.begin(c,e,"CONSIGN",p,input);require("PENDING".equals(text(op,"state")),"原物流回传已登记或结束，请核对原请求");input.put("flow_operation_id",op.get("id"));input.put("automatic_policy_revision",p.get("revision"));execution.request(c,id,input,ExchangeFlowPolicy.ACTOR);return outcome(c,id,v,"WAITING","CONSIGN","CONSIGN_SUBMITTED","已登记本轮实际换出物流，等待平台确认");
    }
    private void reviewReplacementOrder(String c,Map<String,Object> e,Map<String,Object> p){
        Map<String,Object> order=repository.db().queryForMap("SELECT * FROM oms_order WHERE company_code=? AND id=?",c,e.get("order_id"));if("APPROVED".equals(text(order,"review_status")))return;
        require(ExchangeFlowPolicy.on(p,"auto_unshipped"),"未发货换品后的自动审单未启用");policies.requireCurrent(c,number(e,"channel_id"),number(p,"revision"),"auto_unshipped");
        new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource())).execute(tx->{Map<String,Object> current=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",ROW,c,e.get("order_id")).get(0);require(number(current,"manual_hold")==0&&"WAIT_ALLOCATION".equals(text(current,"status")),"原SO存在其他挂起或阶段变化，不能自动审单");require("PENDING".equals(text(current,"review_status"))&&"MANUAL_REQUIRED".equals(text(current,"review_decision"))&&"协商换品后剩余需求待审核".equals(text(current,"review_reason")),"原SO审核原因已变化，请人工核对，不能覆盖其他审核结论");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_line WHERE company_code=? AND order_id=? AND id=? AND exchange_id=? AND business_type='SALE' AND sku_sn=?",Long.class,c,e.get("order_id"),e.get("fulfillment_line_id"),e.get("id"),e.get("target_sku"))==1,"未发换品的有效履约来源尚未完整形成");Map<String,Object> platform=repository.raw(c,number(e,"original_platform_order_id"));current.putAll(platform);String block=OrderReviewPolicy.systemBlock(current);require(block.isEmpty(),block);OrderReviewPolicy.requireRemaining(repository,c,number(e,"order_id"));require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_line WHERE company_code=? AND order_id=? AND business_type='SALE' AND reserved_quantity<quantity-cancelled_quantity",Long.class,c,e.get("order_id"))==0,"原SO仍有其他商品未完成预占，请等待或人工核对");String reason="商家自动换货规则版本 "+p.get("revision")+"；已授权未发换品生效，原平台交易未变化且有效需求完整预占";repository.db().update("UPDATE oms_order SET review_status='APPROVED',review_decision='AUTO_APPROVED',review_by=?,review_at=NOW(),review_reason=?,control_version=control_version+1 WHERE company_code=? AND id=?",ExchangeFlowPolicy.REVIEW_ACTOR,reason,c,e.get("order_id"));repository.db().update("INSERT INTO oms_order_review_event(company_code,order_id,action,decision,assessment,operator_name) VALUES (?,?,'AUTO_EXCHANGE_APPROVE','AUTO_APPROVED',?,?)",c,e.get("order_id"),encode(map("exchange_id",e.get("id"),"policy_revision",p.get("revision"),"reason",reason)),ExchangeFlowPolicy.REVIEW_ACTOR);return null;});
    }
    private Map<String,Object> outcome(String c,long id,long v,String state,String node,String code,String message){repository.db().update("UPDATE oms_exchange_flow_task SET state=?,node=?,last_code=?,last_message=?,next_attempt=IF(?='DONE',NULL,DATE_ADD(NOW(),INTERVAL 30 SECOND)) WHERE company_code=? AND exchange_id=? AND work_version=?",state,node,code,message,state,c,id,v);return map("state",state,"node",node,"code",code,"message",message);}
}
